{"op":"add","path":"/root","value":"pricing-root"}
{"op":"add","path":"/elements/pricing-root","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["page-header","billing-bar","plans-grid","selection-confirm","fine-print"]}}
{"op":"add","path":"/elements/page-header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["page-title","page-subtitle"]}}
{"op":"add","path":"/elements/page-title","value":{"type":"Heading","props":{"text":"Plans that scale with your team","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/page-subtitle","value":{"type":"Text","props":{"text":"Start free, upgrade when you need more power. Switch between monthly and annual billing at any time.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/billing-bar","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["billing-switch","billing-note"]}}
{"op":"add","path":"/elements/billing-switch","value":{"type":"Switch","props":{"label":"Annual billing","description":"Save up to 20% with yearly plans","checked":{"$bindState":"/annual"}},"children":[]}}
{"op":"add","path":"/elements/billing-note","value":{"type":"Text","props":{"text":"Prices in USD, excluding local taxes. Cancel anytime.","variant":"small"},"children":[]}}
{"op":"add","path":"/elements/plans-grid","value":{"type":"Grid","props":{"columns":"3","gap":"md"},"repeat":{"statePath":"/plans","key":"id"},"children":["plan-card"]}}
{"op":"add","path":"/elements/plan-card","value":{"type":"Card","props":{"title":{"$item":"name"},"description":{"$item":"tagline"}},"children":["plan-badge","plan-price","plan-price-annual","plan-separator","plan-features","plan-cta"]}}
{"op":"add","path":"/elements/plan-badge","value":{"type":"Badge","props":{"text":"Most popular","variant":"default"},"visible":{"$item":"popular","eq":true},"children":[]}}
{"op":"add","path":"/elements/plan-price","value":{"type":"Heading","props":{"text":{"$template":"${monthly}/month"},"level":"h2"},"visible":{"$state":"/annual","not":true},"children":[]}}
{"op":"add","path":"/elements/plan-price-annual","value":{"type":"Text","props":{"text":{"$template":"${annual}/month billed annually"},"variant":"muted"},"visible":{"$state":"/annual"},"children":[]}}
{"op":"add","path":"/elements/plan-separator","value":{"type":"Separator","props":{},"children":[]}}
{"op":"add","path":"/elements/plan-features","value":{"type":"List","props":{"items":{"$item":"features"},"ordered":false},"children":[]}}
{"op":"add","path":"/elements/plan-cta","value":{"type":"Button","props":{"label":{"$item":"cta"},"variant":{"$cond":{"$item":"popular"},"$then":"default","$else":"outline"},"size":"default"},"on":{"press":{"action":"setState","params":{"statePath":"/selectedPlan","value":{"$item":"name"}}}},"children":[]}}
{"op":"add","path":"/elements/selection-confirm","value":{"type":"Alert","props":{"title":{"$template":"You selected the ${/selectedPlan} plan"},"description":"Head to checkout to finish setting up your workspace — you can change or cancel your plan at any time.","variant":"default"},"visible":{"$state":"/selectedPlan"},"children":[]}}
{"op":"add","path":"/elements/fine-print","value":{"type":"Text","props":{"text":"Every plan includes unlimited viewers, SOC 2 Type II compliance, and a 14-day Pro trial with no credit card required.","variant":"small"},"children":[]}}
{"op":"add","path":"/state/annual","value":false}
{"op":"add","path":"/state/selectedPlan","value":""}
{"op":"add","path":"/state/plans","value":[]}
